  FROM routes,
       (VALUES (0, 'Potosí'),
               (1, 'Bomberos'),
               (2, 'Colegio La Presentación'),
               (3, 'Pompas La Paz'),
               (4, 'Panadería Filipo (Pekín)'),
               (5, 'Corregimiento'),
               (6, 'Hogar Francisco y Clara'),
               (7, 'Escuela de los Sauces'),
               (8, 'Alaska'),
               (9, 'Buenas Tardes'),
               (10, 'Crucero La Angostura'),
               (11, 'La Capilla'),
               (12, 'Pasca')) AS v(order_index, neighborhood_name)
 WHERE sign_file = 'PASCA';

